const lead = $input.first().json;

const alert = {
  event: 'HTGF_LEAD_DISPATCH',
  timestamp: new Date().toISOString(),
  entity_id: lead.entity_id || lead.id,
  company_name: lead.name || lead.canonical_name,
  vertical: lead.htgf_vertical || 'deeptech',
  score: lead.deterministic_score || lead.score,
  ml_tier: (lead.ml_score && lead.ml_score >= 0.85) ? 'TIER_1_MUST_INVEST' : 'TIER_2_PRIORITY',
  founders: (lead.founders || []).map(f => ({
    name: f.full_name || f.name,
    linkedin: f.linkedin_url,
    github: f.github_handle
  })),
  memo_summary: lead.memo ? lead.memo.summary : lead.funding_summary
};

return [{ json: { status: 'success', dispatched: true, alert: alert } }];
